import{_ as s,C as t,o as i,c as n,a5 as r,E as l,j as a,a as d}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"Leer e inspeccionar el feed LIVE","description":"","frontmatter":{"title":"Leer e inspeccionar el feed LIVE","docId":"user.live.feed","translationKey":"user.live.feed","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","translationRevision":"cdc714d3e543d3290edf372fdd0b3fcd9f678a1374cd82ac291cf1a2fa632ca1","order":20},"headers":[],"relativePath":"es/user/live/feed.md","filePath":"es/user/live/feed.md","lastUpdated":1794611623000}'),c={name:"es/user/live/feed.md"};function u(p,e,m,f,v,h){const o=t("DemoFrame");return i(),n("div",null,[e[0]||(e[0]=r('<h1 id="read-and-inspect-the-live-feed" tabindex="-1">Leer e inspeccionar el feed LIVE <a class="header-anchor" href="#read-and-inspect-the-live-feed" aria-label="Permalink to &quot;Leer e inspeccionar el feed LIVE {#read-and-inspect-the-live-feed}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Encuentra un evento, inspecciona sus campos y distingue una vista pausada de una sala desconectada. Comienza con una <a href="./connections.html">conexión LIVE</a> o utiliza los eventos que ya están en el feed actual. El feed es una vista de trabajo limitada, no una grabación completa de la transmisión.</p><h2 id="inspect-activity" tabindex="-1">Inspeccionar la actividad <a class="header-anchor" href="#inspect-activity" aria-label="Permalink to &quot;Inspeccionar la actividad {#inspect-activity}&quot;">​</a></h2><ol><li>Abre <strong>Live feed</strong> y confirma el creador activo en el estado de conexión.</li><li>Elige un filtro: todos los eventos, chat, regalos, likes, seguidores, entradas u otra actividad social. Combínalo con la búsqueda para localizar un autor, mensaje, nombre de regalo o ID exacto del regalo.</li><li>Pulsa <strong>Pause</strong> para detener el desplazamiento automático mientras lees. Pueden seguir llegando eventos y aumentar el contador de pendientes. Este control no desconecta TikTok ni suspende automatizaciones.</li><li>Selecciona un evento para abrir su inspector. Lee el tipo y los detalles disponibles antes de elegir campos de automatización. No todos los eventos incluyen texto de chat, datos de regalos o identidad del espectador.</li><li>Selecciona el nombre o avatar de un espectador para revisar su perfil registrado. Usa el control del inspector si el panel de detalles está oculto.</li><li>Pulsa <strong>Resume</strong> o el botón de salto a eventos pendientes para volver a la actividad entrante. Borra la búsqueda y selecciona todos los eventos al comprobar si llega actividad.</li></ol><p>Utiliza los controles etiquetados con el foco del teclado cuando sea posible. Pausar el desplazamiento ayuda cuando el movimiento dificulta leer. Si falta un avatar, se muestran iniciales; la imagen no es necesaria para identificar al espectador.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Los filtros y la inspección están disponibles. Con mucho tráfico, la interfaz puede limitar las filas dibujadas y avisar de eventos omitidos en la vista. Estos indicadores describen la presentación; no uses el número de filas visibles como total contable. <a href="./../points/statistics.html">Estadísticas</a> consulta agregados persistentes por separado.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si no ves eventos, elimina filtros, reanuda el desplazamiento y revisa la conexión. Una sala tranquila puede funcionar correctamente. Reconectar al mismo creador conserva el contexto; cambiarlo lo sustituye. <strong>Clear</strong> vacía el feed de trabajo y no reinicia puntos ni estadísticas. Investiga los avisos mediante <a href="./../preferences/troubleshooting.html">diagnósticos</a>, sin asumir que cada fila ausente representa una pérdida del evento original.</p>',10)),l(o,{scenario:"feed",locale:"es",title:"Demo de feed"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[d("Detalles de operación "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalles de operación {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Esta versión conserva hasta 300 eventos en pantalla y prepara hasta 900 mientras espera la presentación. Expulsa primero la fila no regalo más antigua; solo expulsa regalos cuando no quedan otros tipos. Un regalo antiguo puede permanecer más que un chat reciente. Pausar el desplazamiento no detiene la entrada ni garantiza conservarla. Los filtros no recuperan filas expulsadas; un aviso de pérdida indica una vista incompleta, no autorización para repetir puntos o acciones.",-1))])}const y=s(c,[["render",u]]);export{g as __pageData,y as default};
